const common={
 action:{accessibility:pair('Use a meaningful localized accessible name, visible keyboard focus and at least a 48px touch target. Native buttons activate with Enter/Space. Explain unavailable actions nearby.','استخدم اسماً واضحاً ومترجماً وتركيزاً مرئياً ومساحة لمس لا تقل عن ٤٨ بكسل. تُفعّل الأزرار بـ Enter أو Space. وضّح سبب عدم الإتاحة بجوار الإجراء.'),responsive:pair('Allow labels and surrounding action groups to wrap. Test narrow parent constraints and enlarged text; do not reduce the touch target to fit.','اسمح بالتفاف النصوص ومجموعات الأزرار. اختبر العرض الضيق والنص المكبر دون تقليص مساحة اللمس.'),rtl:pair('Supply translated labels from the application and inherit document dir/Flutter Directionality. Use directional padding; mirror navigation arrows, not logos or arbitrary icons.','زوّد النصوص المترجمة من التطبيق واتبع اتجاه المستند أو Directionality. استخدم هوامش اتجاهية واعكس أسهم التنقل دون الشعارات أو الرموز الأخرى.')},
 display:{accessibility:pair('Keep meaningful text in reading order and preserve text contrast in all themes. This display surface is not automatically a button or live region; added actions need their own semantics.','حافظ على ترتيب قراءة واضح وتباين النص في جميع المظاهر. عنصر العرض ليس زراً أو منطقة إعلان تلقائياً؛ الإجراءات المضافة تحتاج دلالاتها الخاصة.'),responsive:pair('Size to the available parent width and let text grow vertically. Put long collections in a scroll view owned by the page; avoid fixed heights that clip enlarged text.','التزم بعرض الحاوية المتاح واسمح بامتداد النص عمودياً. ضع المجموعات الطويلة داخل تمرير تديره الصفحة وتجنب ارتفاعات تقطع النص المكبر.'),rtl:pair('Translate supplied text and inherit RTL. Format dates, currency and numbers in the application; isolate mixed-direction identifiers and keep reading order meaningful.','ترجم النصوص واتبع اتجاه العربية. نسّق التواريخ والعملات والأرقام في التطبيق واعزل المعرّفات المختلطة الاتجاه مع الحفاظ على ترتيب القراءة.')},
 layout:{accessibility:pair('Layout creates no interactive semantics. Preserve source/reading order, meaningful headings and focus order; children remain responsible for labels and touch targets.','التخطيط لا يضيف دلالات تفاعل. حافظ على ترتيب المصدر والقراءة والتركيز والعناوين الصحيحة؛ المكونات الداخلية مسؤولة عن تسمياتها ومساحات لمسها.'),responsive:pair('Respect bounded width and content-driven height. Let the page own scrolling and test 360px parents with enlarged text; avoid unbounded flex children inside scroll axes.','احترم حدود العرض وارتفاع المحتوى. اجعل الصفحة تدير التمرير واختبر عرض ٣٦٠ بكسل مع نص مكبر؛ تجنب عناصر flex غير المحدودة داخل محور التمرير.'),rtl:pair('Use logical start/end alignment and preserve source order. Directionality controls visual direction; the application still supplies translated child content.','استخدم محاذاة البداية والنهاية المنطقية وحافظ على ترتيب المصدر. يتحكم Directionality في الاتجاه المرئي ويوفر التطبيق ترجمة المحتوى.')},
 navigation:{accessibility:pair('Give the navigation region a localized name and expose the current item with role-appropriate selected/current semantics. Keep focus visible and use genuine destinations or buttons.','سمِّ منطقة التنقل باسم مترجم وحدد العنصر الحالي بدلالات selected أو current المناسبة. حافظ على التركيز المرئي واستخدم روابط أو أزراراً حقيقية.'),responsive:pair('Wrap destinations when appropriate; preserve minimum touch targets and provide scrolling or a drawer for constrained screens. Test long translated labels.','اسمح بالتفاف الوجهات عند الحاجة وحافظ على مساحات اللمس؛ استخدم التمرير أو درج التنقل للشاشات الضيقة واختبر النصوص المترجمة الطويلة.'),rtl:pair('Translate destination labels, inherit RTL and mirror directional navigation cues. Selection and route IDs stay stable when language changes.','ترجم أسماء الوجهات واتبع اتجاه العربية واعكس إشارات التنقل الاتجاهية. تبقى هوية الوجهة والتحديد مستقرة عند تبديل اللغة.')},
 overlay:{accessibility:pair('Provide a labelled trigger and a titled surface with an explicit localized close action. Check keyboard focus, Escape dismissal and focus return; modal and nonmodal surfaces have different contracts.','وفّر زر فتح مسمى وسطحاً ذا عنوان وزر إغلاق مترجماً. اختبر التركيز وEscape وعودة التركيز؛ يختلف سلوك الحوار المشروط عن النافذة غير المشروطة.'),responsive:pair('Constrain the surface to the viewport, account for safe areas/keyboard insets and scroll long content. Avoid a fixed height that hides the close action.','احصر السطح داخل الشاشة وراعِ المناطق الآمنة ومساحة لوحة المفاتيح ومرّر المحتوى الطويل. تجنب ارتفاعاً ثابتاً يخفي زر الإغلاق.'),rtl:pair('Translate trigger, title, content and close text. Use logical alignment; verify the anchor and focus return in RTL as well as LTR.','ترجم زر الفتح والعنوان والمحتوى والإغلاق. استخدم المحاذاة المنطقية واختبر الموضع وعودة التركيز في الاتجاهين.')},
};
